from __future__ import annotations

import sys
from typing import IO

from secretscan.model import Finding, Module, RunMeta

_COLORS = {
    "critical": "\033[91m",
    "high": "\033[93m",
    "medium": "\033[33m",
    "low": "\033[37m",
    "reset": "\033[0m",
    "bold": "\033[1m",
    "dim": "\033[2m",
    "header": "\033[96m",
}


def _c(color: str, text: str, no_color: bool) -> str:
    if no_color:
        return text
    return f"{_COLORS.get(color, '')}{text}{_COLORS['reset']}"


def _categorize(findings: list[Finding]) -> dict[str, list[Finding]]:
    cats: dict[str, list[Finding]] = {
        "regular": [], "private_keys": [], "keychain": [],
        "process_env": [], "placeholders": [],
    }
    for f in findings:
        if f.file_identity:
            cats["private_keys"].append(f)
        elif f.module == Module.KEYCHAIN:
            cats["keychain"].append(f)
        elif f.module == Module.PROCESS_ENV:
            cats["process_env"].append(f)
        elif f.placeholder:
            cats["placeholders"].append(f)
        else:
            cats["regular"].append(f)
    return cats


def _print_findings_table(w: IO[str], title: str, findings: list[Finding], no_color: bool) -> None:
    if not findings:
        return
    w.write(f"\n{_c('bold', f'  {title} ({len(findings)})', no_color)}\n")
    w.write(f"  {'─' * 80}\n")

    for f in findings:
        sev = _c(f.severity.value, f"  [{f.severity.value.upper()}]", no_color)
        extra = f" (+{len(f.additional_files)} more file(s))" if f.additional_files else ""
        w.write(f"{sev} {f.rule_id}\n")
        w.write(f"      {_c('dim', f.location + extra, no_color)}\n")
        w.write(f"      {f.redacted_value}\n")
        if f.redacted_context and f.redacted_context != f.redacted_value:
            ctx = f.redacted_context[:120]
            w.write(f"      {_c('dim', ctx, no_color)}\n")
        w.write(f"      {_c('dim', f'fingerprint: {f.fingerprint}', no_color)}\n\n")


def render_table(w: IO[str], findings: list[Finding], meta: RunMeta, no_color: bool = False) -> None:
    if no_color is False and not (hasattr(w, "isatty") and w.isatty()):
        no_color = True

    w.write(f"\n{_c('bold', '  secretscan report', no_color)}\n")
    w.write(f"  {'═' * 80}\n")
    w.write(f"  Host: {meta.hostname}\n")
    w.write(f"  Scanned: {', '.join(meta.paths)}\n")
    w.write(f"  Modules: {', '.join(m.value for m in meta.modules)}\n")

    if meta.started_at and meta.finished_at:
        elapsed = (meta.finished_at - meta.started_at).total_seconds()
        w.write(f"  Duration: {elapsed:.1f}s\n")

    for st in meta.module_statuses:
        w.write(f"  {_c('dim', f'  {st.module.value}: {st.accessed}/{st.attempted} accessed', no_color)}")
        if st.note:
            w.write(f" {_c('dim', f'({st.note[:80]})', no_color)}")
        w.write("\n")

    if meta.severity_counts:
        counts = " | ".join(
            f"{_c(sev, f'{sev}: {count}', no_color)}"
            for sev, count in sorted(meta.severity_counts.items(), key=lambda x: -{"critical": 4, "high": 3, "medium": 2, "low": 1}.get(x[0], 0))
        )
        w.write(f"\n  {counts}\n")

    cats = _categorize(findings)
    _print_findings_table(w, "Findings", cats["regular"], no_color)
    _print_findings_table(w, "Private Keys", cats["private_keys"], no_color)
    _print_findings_table(w, "Keychain Items", cats["keychain"], no_color)
    _print_findings_table(w, "Running Processes", cats["process_env"], no_color)

    if meta.listeners:
        w.write(f"\n{_c('bold', f'  Listening Ports ({len(meta.listeners)})', no_color)}\n")
        w.write(f"  {'─' * 80}\n")
        for l in meta.listeners:
            exposure_color = "critical" if l.exposure == "all interfaces" else "dim"
            w.write(f"  {l.proto:4s} {l.address}:{l.port:6s} {l.process_name} (pid {l.pid}) ")
            w.write(f"{_c(exposure_color, l.exposure, no_color)}")
            if l.sockets > 1:
                w.write(f" x{l.sockets}")
            w.write("\n")

    if meta.tools:
        curated = [t for t in meta.tools if t.curated]
        if curated:
            w.write(f"\n{_c('bold', f'  Installed Tools ({len(curated)} curated)', no_color)}\n")
            w.write(f"  {'─' * 80}\n")
            for t in curated:
                w.write(f"  {t.name:20s} {t.version[:60]:60s} {_c('dim', t.source, no_color)}\n")

    if meta.docker:
        w.write(f"\n{_c('bold', '  Docker', no_color)}\n")
        w.write(f"  {'─' * 80}\n")
        w.write(f"  Installed: {meta.docker.installed}  Daemon: {meta.docker.daemon_running}\n")
        if meta.docker.api_exposed:
            w.write(f"  {_c('critical', 'WARNING: Docker API exposed on localhost:2375!', no_color)}\n")
        for c in meta.docker.containers:
            exposed = _c("critical", "EXPOSED", no_color) if c.exposed else _c("dim", "local", no_color)
            w.write(f"  {c.name:20s} {c.image:30s} {exposed} {', '.join(c.ports)}\n")

    if meta.internet:
        w.write(f"\n{_c('bold', '  Internet Connectivity', no_color)}\n")
        w.write(f"  {'─' * 80}\n")
        if meta.internet.public_ip:
            w.write(f"  Public IP: {meta.internet.public_ip}\n")
        for chk in meta.internet.checks:
            status_str = _c("bold", "✓", no_color) if chk.reachable else _c("critical", "✗", no_color)
            w.write(f"  {status_str} {chk.name:30s} {chk.host}:{chk.port}\n")

    if meta.lan_devices:
        w.write(f"\n{_c('bold', f'  Local Network Devices ({len(meta.lan_devices)})', no_color)}\n")
        w.write(f"  {'─' * 80}\n")
        for dev in meta.lan_devices:
            w.write(f"  {dev.ip:16s} {dev.mac:18s} {dev.hostname}\n")

    _print_findings_table(w, "Likely Placeholders", cats["placeholders"], no_color)

    if not findings:
        w.write(f"\n  {_c('bold', 'No findings.', no_color)}\n")

    w.write(f"\n  {'═' * 80}\n\n")
